import {language,t} from './i18n.js?v=56705894646a';
import {validTimeZone,zonedDateTime,zonedDateTimeToUtc,agreementText,agreementCalendar,agreementPrintHTML} from './group-agreements-export.js?v=56705894646a';
const $=id=>document.getElementById(id),make=(tag,cls,text)=>{const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;};
const fields=['title','roles','meetingAgenda','communication','responseTime','clarification','breaks'];
const limits={title:120,roles:1000,meetingAgenda:1000,communication:600,responseTime:300,clarification:600,breaks:600};
const localZone=()=>{const zone=Intl.DateTimeFormat().resolvedOptions().timeZone;return validTimeZone(zone)?zone:'UTC';};
const knownZones=()=>{const zones=typeof Intl.supportedValuesOf==='function'?Intl.supportedValuesOf('timeZone'):['Asia/Shanghai','Asia/Hong_Kong','Asia/Tokyo','Europe/Amsterdam','Europe/London','Europe/Paris','America/New_York','America/Toronto','America/Los_Angeles','Australia/Sydney'];return [...new Set(['UTC',localZone(),...zones])];};

export function initGroupAgreements({state,api,run,button,toast,requireMember,confirm}){
 let account=null,epoch=0,listRequest=0,detailRequest=0,historyRequest=0,groups=[],loaded=false,loadingList=false,loadingDetail=false,writing=false,activeId=null,agreement=null,baseRevision=null,editorTasks=[],baseline='',dirty=false,errorKey=null,freshInvite=null,versions=[],selectedVersion=null;
 const current=(id,version)=>state.profile?.id===id&&account===id&&epoch===version;
 const owner=()=>agreement?.ownerId===state.profile?.id;
 const stamp=value=>new Intl.DateTimeFormat(language==='zh'?'zh-CN':'en',{dateStyle:'medium',timeStyle:'short'}).format(new Date(value));
 const groupPath=id=>'/group-agreements/'+encodeURIComponent(id);
 function rawEditor(){return {...Object.fromEntries(fields.map(key=>[key,$('agreement-'+key).value])),tasks:editorTasks.map(task=>({id:task.id,text:task.text,assigneeId:task.assigneeId,deadlineInput:task.deadlineInput,timeZone:task.timeZone}))};}
 function markDirty(){dirty=JSON.stringify(rawEditor())!==baseline;renderControls();}
 function dropActive(){activeId=null;agreement=null;baseRevision=null;editorTasks=[];baseline='';dirty=false;freshInvite=null;versions=[];selectedVersion=null;detailRequest++;historyRequest++;loadingDetail=false;for(const key of fields)$('agreement-'+key).value='';$('agreement-task-list').replaceChildren();$('agreement-members').replaceChildren();$('agreement-invitations').replaceChildren();$('agreement-history-list').replaceChildren();$('agreement-version-preview').textContent='';$('agreement-fresh-code').value='';render();}
 function resetMembers(){epoch++;listRequest++;detailRequest++;historyRequest++;account=null;groups=[];loaded=false;loadingList=false;loadingDetail=false;writing=false;errorKey=null;$('agreement-create-form').reset();$('agreement-join-form').reset();dropActive();render();}
 function memberChanged(){const next=state.profile?.id||null;if(next!==account){resetMembers();account=next;}render();if(next&&!loaded&&!loadingList)run(null,loadList);}
 function renderControls(){const member=!!state.profile,busy=writing||loadingDetail,exists=!!agreement,changed=exists&&baseRevision!==agreement.revision;$('agreements-join-account').hidden=member;$('agreements-refresh-list').disabled=!member||loadingList||writing;for(const id of ['agreement-create-title','agreement-join-code','agreement-create','agreement-join'])$(id).disabled=!member||writing;$('agreement-sheet-fields').disabled=!member||!exists||busy;$('agreement-refresh').disabled=!exists||busy;$('agreement-save').disabled=!exists||busy||!dirty;$('agreement-confirm').disabled=!exists||busy||dirty||changed||agreement.members?.find(item=>item.id===state.profile?.id)?.confirmedRevision===agreement.revision;$('agreement-unsaved').hidden=!dirty;$('agreement-newer').hidden=!changed;$('agreement-load-latest').disabled=busy;$('agreement-add-task').disabled=busy||editorTasks.length>=20;for(const id of ['agreement-export-text','agreement-print','agreement-export-calendar','agreement-calendar-alert'])$(id).disabled=!exists||busy||dirty||changed;$('agreement-load-history').disabled=!exists||busy;$('agreement-restore-version').disabled=!exists||busy||!selectedVersion;$('agreement-create-invite').disabled=!exists||!owner()||busy||(agreement.invitations?.length||0)>=5||(agreement.members?.length||0)>=12;$('agreement-leave').hidden=!exists||owner();$('agreement-delete').hidden=!exists||!owner();$('agreement-leave').disabled=busy;$('agreement-delete').disabled=busy;$('agreement-error-placeholder')?.remove();$('agreements-error').hidden=!errorKey;if(errorKey)$('agreements-error').textContent=t(errorKey);}
 function renderList(){const list=$('agreement-list');list.replaceChildren();if(!state.profile)return;if(!groups.length){list.append(make('p','small',t(loadingList?'agreementsLoading':'agreementsNoGroups')));return;}for(const group of groups){if(group.unavailable){const card=make('div','agreement-group-unavailable');card.append(make('p','small',t('agreementsUnavailable')));const actions=make('div','resource-actions');if(group.mine){actions.append(button('agreementsRemoveBlocked',()=>confirm('agreementsRemoveBlockedConfirm',()=>mutate(()=>api(groupPath(group.id)+'/remove-blocked','POST',{}),async()=>{await loadList();toast('agreementsMemberRemoved');},group.id)),'secondary'),button('agreementsDelete',()=>deleteGroup(group.id),'text-button'));}else actions.append(button('agreementsLeave',()=>leaveGroup(group.id),'text-button'));card.append(actions);list.append(card);continue;}const control=make('button','agreement-group-button');control.type='button';control.setAttribute('aria-current',String(activeId===group.id));control.append(make('strong','',group.title),make('span','',t('agreementsVersion')+' '+group.revision+' · '+group.memberCount+' '+t('agreementsMemberCount')+(group.mine?' · '+t('agreementsOwner'):'')));control.disabled=writing;control.onclick=()=>run(control,()=>chooseGroup(group.id));list.append(control);}}
 function taskLabel(key,suffix=''){const label=make('label','',t(key)+(suffix?' '+suffix:''));label.dataset.agreementTaskKey=key;label.dataset.agreementTaskSuffix=suffix;return label;}
 function fillAssignees(select,task){select.replaceChildren();const blank=make('option','',t('agreementsUnassigned'));blank.value='';select.append(blank);for(const member of agreement.members||[]){const option=make('option','',member.name);option.value=member.id;select.append(option);}if(task.assigneeId&&!agreement.members.some(member=>member.id===task.assigneeId)){const previous=make('option','',t('agreementsFormerMember'));previous.value=task.assigneeId;select.append(previous);}select.value=task.assigneeId||'';}
 function renderTasks(){const list=$('agreement-task-list');list.replaceChildren();for(const [index,task] of editorTasks.entries()){const card=make('div','agreement-task'),textId='agreement-task-'+task.id,textLabel=taskLabel('agreementsTaskText',String(index+1)),text=make('textarea');textLabel.htmlFor=textId;text.id=textId;text.rows=2;text.maxLength=200;text.required=true;text.value=task.text;text.placeholder=t('agreementsTaskHint');text.dataset.agreementTaskText='1';text.oninput=()=>{task.text=text.value;markDirty();};card.append(textLabel,text);const meta=make('div','agreement-task-meta');for(const key of ['assignee','deadline','zone']){const box=make('div'),label=taskLabel(key==='assignee'?'agreementsAssignee':key==='deadline'?'agreementsDeadline':'agreementsTimeZone'),control=make(key==='deadline'?'input':'select');control.id=textId+'-'+key;label.htmlFor=control.id;if(key==='assignee'){control.dataset.taskAssignee=task.id;fillAssignees(control,task);control.onchange=()=>{task.assigneeId=control.value||null;markDirty();};}else if(key==='deadline'){control.type='datetime-local';control.value=task.deadlineInput;control.oninput=()=>{task.deadlineInput=control.value;markDirty();};}else{for(const zone of [...new Set([task.timeZone,...knownZones()])]){const option=make('option','',zone);option.value=zone;control.append(option);}control.value=task.timeZone;control.onchange=()=>{task.timeZone=control.value;markDirty();};}box.append(label,control);meta.append(box);}card.append(meta);const actions=make('div','resource-actions');for(const [key,offset] of [['agreementsTaskUp',-1],['agreementsTaskDown',1]]){const move=button(key,()=>{const at=editorTasks.findIndex(item=>item.id===task.id),next=at+offset;if(next<0||next>=editorTasks.length)return;[editorTasks[at],editorTasks[next]]=[editorTasks[next],editorTasks[at]];renderTasks();markDirty();$('agreement-task-'+task.id).focus();},'text-button');move.dataset.agreementTaskAction=key;move.disabled=index+offset<0||index+offset>=editorTasks.length;actions.append(move);}const remove=button('agreementsRemoveTask',()=>{editorTasks=editorTasks.filter(item=>item.id!==task.id);renderTasks();markDirty();$('agreement-add-task').focus();},'text-button');remove.dataset.agreementTaskAction='agreementsRemoveTask';actions.append(remove);card.append(actions);list.append(card);}renderControls();}
 function renderTaskLabels(){for(const label of $('agreement-task-list').querySelectorAll('[data-agreement-task-key]'))label.textContent=t(label.dataset.agreementTaskKey)+(label.dataset.agreementTaskSuffix?' '+label.dataset.agreementTaskSuffix:'');for(const control of $('agreement-task-list').querySelectorAll('[data-agreement-task-action]'))control.textContent=t(control.dataset.agreementTaskAction);for(const text of $('agreement-task-list').querySelectorAll('[data-agreement-task-text]'))text.placeholder=t('agreementsTaskHint');if(agreement)for(const select of $('agreement-task-list').querySelectorAll('[data-task-assignee]')){const task=editorTasks.find(item=>item.id===select.dataset.taskAssignee);if(task)fillAssignees(select,task);}}
 function fillEditor(){for(const key of fields)$('agreement-'+key).value=agreement[key]||'';editorTasks=(agreement.tasks||[]).map(task=>({...task,timeZone:task.timeZone||localZone(),deadlineInput:zonedDateTime(task.deadline,task.timeZone||localZone()),originalDeadline:task.deadline,originalZone:task.timeZone||localZone()}));baseRevision=agreement.revision;renderTasks();baseline=JSON.stringify(rawEditor());dirty=false;}
 function applyAgreement(value,preserve=false){const keep=preserve&&dirty;agreement=value;activeId=value.id;if(!keep)fillEditor();render();}
 function renderMembers(){const list=$('agreement-members');list.replaceChildren();if(!agreement)return;for(const member of agreement.members||[]){const row=make('div','agreement-member'),info=make('div');info.append(make('strong','',member.name+(member.id===state.profile?.id?' · '+t('agreementsYou'):'')),make('small','',t(member.id===agreement.ownerId?'agreementsOwner':member.confirmedRevision===agreement.revision?'agreementsReviewed':'agreementsNotReviewed')));if(member.id===agreement.ownerId)info.append(make('small','',t(member.confirmedRevision===agreement.revision?'agreementsReviewed':'agreementsNotReviewed')));row.append(info);if(owner()&&member.id!==agreement.ownerId){const remove=button('agreementsRemoveMember',()=>confirm('agreementsRemoveMemberConfirm',()=>mutate(()=>api(groupPath(activeId)+'/members/'+encodeURIComponent(member.id),'DELETE'),async()=>{await loadAgreement(activeId,true);await loadList();toast('agreementsMemberRemoved');},activeId)),'text-button');remove.disabled=writing;row.append(remove);}list.append(row);}}
 function renderInvites(){$('agreement-owner-tools').hidden=!agreement||!owner();$('agreement-fresh-invite').hidden=!freshInvite;if(freshInvite)$('agreement-fresh-code').value=freshInvite.code;const list=$('agreement-invitations');list.replaceChildren();if(!agreement||!owner())return;const invites=agreement.invitations||[];if(!invites.length)list.append(make('p','small',t('agreementsNoInvites')));for(const invite of invites){const row=make('div','agreement-invitation');row.append(make('span','small',t('agreementsInviteExpires')+' · '+stamp(invite.expires)));const revoke=button('agreementsRevokeInvite',()=>mutate(()=>api(groupPath(activeId)+'/invites/'+encodeURIComponent(invite.id),'DELETE'),async()=>{if(freshInvite?.id===invite.id)freshInvite=null;await loadAgreement(activeId,true);toast('agreementsInviteRevoked');},activeId),'text-button');revoke.disabled=writing;row.append(revoke);list.append(row);}}
 function renderHistory(){const list=$('agreement-history-list');list.replaceChildren();for(const version of versions){const control=button(t('agreementsVersion')+' '+version.revision,()=>viewVersion(version.revision),'secondary');control.disabled=writing;list.append(control);}$('agreement-history-preview').hidden=!selectedVersion;if(selectedVersion)$('agreement-version-preview').textContent=agreementText({...selectedVersion,members:agreement?.members||[]},language,{includeMembers:false});}
 function render(){renderList();$('agreement-empty').hidden=!!agreement;$('agreement-active').hidden=!agreement;if(agreement){$('agreement-sheet-title').textContent=agreement.title;$('agreement-version').textContent=t('agreementsVersion')+' '+agreement.revision;renderTaskLabels();renderMembers();renderInvites();renderHistory();}renderControls();}
 async function loadList(){if(!state.profile)return;const id=state.profile.id,version=epoch,sequence=++listRequest;loadingList=true;render();try{const result=await api('/group-agreements');if(!current(id,version)||sequence!==listRequest)return;groups=result.agreements||[];loaded=true;if(activeId&&!groups.some(group=>group.id===activeId&&!group.unavailable)){dropActive();errorKey='agreementsUnavailable';}render();}catch(error){if(current(id,version)&&sequence===listRequest){errorKey=error.message;render();throw error;}}finally{if(current(id,version)&&sequence===listRequest){loadingList=false;render();}}}
 async function loadAgreement(groupId,preserve=false){if(!state.profile)return;const id=state.profile.id,version=epoch,sequence=++detailRequest;loadingDetail=true;render();try{const result=await api(groupPath(groupId));if(!current(id,version)||sequence!==detailRequest||activeId!==groupId)return;applyAgreement(result.agreement,preserve);}catch(error){if(current(id,version)&&sequence===detailRequest){errorKey=error.message;if(['notFound','agreementUnavailable','blocked'].includes(error.message)){dropActive();errorKey='agreementsUnavailable';}render();throw error;}}finally{if(current(id,version)&&sequence===detailRequest){loadingDetail=false;render();}}}
 async function selectGroup(groupId){activeId=groupId;agreement=null;baseRevision=null;editorTasks=[];baseline='';dirty=false;freshInvite=null;versions=[];selectedVersion=null;render();await loadAgreement(groupId);}
 function chooseGroup(groupId){if(activeId===groupId)return;if(dirty){confirm('agreementsDiscardEditsConfirm',()=>selectGroup(groupId));return;}return selectGroup(groupId);}
 async function mutate(action,done,groupId=null){if(!requireMember()||writing)return;const id=state.profile.id,version=epoch;writing=true;errorKey=null;render();try{const result=await action();if(!current(id,version))return;await done(result);}catch(error){if(current(id,version)){errorKey=error.message;if(groupId&&['notFound','agreementUnavailable','blocked'].includes(error.message)){dropActive();errorKey='agreementsUnavailable';run(null,loadList);}if(error.message==='agreementConflict'&&activeId)await loadAgreement(activeId,true).catch(()=>{});render();throw error;}}finally{if(current(id,version)){writing=false;render();}}}
 function sheetInput(){const input=Object.fromEntries(fields.map(key=>[key,$('agreement-'+key).value.trim()]));if(!input.title||input.title.length>120)throw Error('agreementsInvalidTitle');for(const key of fields)if(input[key].length>limits[key])throw Error('agreementsTooLong');if(editorTasks.length>20)throw Error('agreementsInvalidTask');input.tasks=editorTasks.map(task=>{const text=task.text.trim();if(!text||text.length>200)throw Error('agreementsInvalidTask');if(!validTimeZone(task.timeZone))throw Error('agreementsInvalidZone');const unchanged=task.originalZone===task.timeZone&&task.deadlineInput===zonedDateTime(task.originalDeadline,task.timeZone),deadline=unchanged?task.originalDeadline:zonedDateTimeToUtc(task.deadlineInput,task.timeZone);return {id:task.id,text,assigneeId:task.assigneeId||null,deadline:deadline??null,timeZone:task.timeZone};});input.expectedRevision=baseRevision;if(new TextEncoder().encode(JSON.stringify(input)).length>30000)throw Error('agreementsTooLong');return input;}
 async function saveSheet(){if(!agreement||!dirty)return;const input=sheetInput(),id=activeId;await mutate(()=>api(groupPath(id),'PUT',input),async result=>{applyAgreement(result.agreement);versions=[];selectedVersion=null;await loadList();toast('agreementsSaved');},id);}
 function createGroup(){const action=()=>{const title=$('agreement-create-title').value.trim();if(!title||title.length>120)throw Error('agreementsInvalidTitle');return mutate(()=>api('/group-agreements','POST',{title}),async result=>{$('agreement-create-form').reset();freshInvite=null;versions=[];selectedVersion=null;applyAgreement(result.agreement);await loadList();toast('agreementsCreated');});};if(dirty)confirm('agreementsDiscardEditsConfirm',action);else return action();}
 function joinGroup(){const action=()=>{const code=$('agreement-join-code').value.trim();return mutate(()=>api('/group-agreements/join','POST',{code}),async result=>{$('agreement-join-form').reset();freshInvite=null;versions=[];selectedVersion=null;if(result.agreement)applyAgreement(result.agreement);await loadList();toast('agreementsJoined');});};if(dirty)confirm('agreementsDiscardEditsConfirm',action);else return action();}
 function deleteGroup(id){confirm('agreementsDeleteConfirm',()=>mutate(()=>api(groupPath(id),'DELETE'),async()=>{if(activeId===id)dropActive();await loadList();toast('agreementsDeleted');},id));}
 function leaveGroup(id){confirm('agreementsLeaveConfirm',()=>mutate(()=>api(groupPath(id)+'/members/'+encodeURIComponent(state.profile.id),'DELETE'),async()=>{if(activeId===id)dropActive();await loadList();toast('agreementsLeft');},id));}
 async function loadHistory(){if(!agreement)return;const id=state.profile.id,version=epoch,groupId=activeId,sequence=++historyRequest,result=await api(groupPath(groupId)+'/versions');if(!current(id,version)||activeId!==groupId||sequence!==historyRequest)return;versions=result.versions||[];renderHistory();if(!versions.length)toast('agreementsNoHistory');}
 async function viewVersion(revision){if(!agreement)return;const id=state.profile.id,version=epoch,groupId=activeId,sequence=++historyRequest,result=await api(groupPath(groupId)+'/versions/'+revision);if(!current(id,version)||activeId!==groupId||sequence!==historyRequest)return;selectedVersion=result.version;renderHistory();renderControls();$('agreement-version-preview').scrollIntoView({block:'nearest',behavior:'instant'});}
 function restoreVersion(){if(!selectedVersion||!agreement)return;const id=activeId,revision=selectedVersion.revision,expectedRevision=agreement.revision;confirm('agreementsRestoreConfirm',()=>mutate(()=>api(groupPath(id)+'/versions/'+revision+'/restore','POST',{expectedRevision}),async result=>{applyAgreement(result.agreement);versions=[];selectedVersion=null;await loadHistory();await loadList();toast('agreementsRestored');},id));}
 function download(contents,type,extension){const url=URL.createObjectURL(new Blob([contents],{type})),link=make('a');link.href=url;link.download='drfrog-group-'+activeId+'-v'+agreement.revision+'.'+extension;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);}
 function printSheet(){if(!agreement||dirty)return;const popup=window.open('','_blank');if(!popup){toast('agreementsPrintBlocked');return;}popup.opener=null;popup.document.open();popup.onload=()=>{try{popup.focus();popup.print();}catch{toast('agreementsPrintBlocked');}};popup.document.write(agreementPrintHTML(agreement,language));popup.document.close();}
 function invalidate(){if(!state.profile)return;const member=state.profile.id,version=++epoch,priorId=activeId,snapshot=agreement&&dirty?rawEditor():null,priorRevision=baseRevision,priorBaseline=baseline;listRequest++;detailRequest++;historyRequest++;groups=[];loaded=false;loadingList=false;writing=false;dropActive();run(null,async()=>{await loadList();if(!current(member,version)||writing||activeId)return;if(priorId&&groups.some(group=>group.id===priorId&&!group.unavailable)){await selectGroup(priorId);if(!current(member,version))return;if(snapshot&&agreement?.id===priorId){for(const key of fields)$('agreement-'+key).value=snapshot[key];editorTasks=snapshot.tasks.map(task=>{const saved=agreement.tasks.find(item=>item.id===task.id);return {...task,originalDeadline:saved?.deadline??null,originalZone:saved?.timeZone||task.timeZone};});baseRevision=priorRevision;baseline=priorBaseline;renderTasks();markDirty();render();}}});}
 for(const key of fields)$('agreement-'+key).addEventListener('input',markDirty);
 $('agreement-create-form').onsubmit=event=>{event.preventDefault();run($('agreement-create'),createGroup);};$('agreement-join-form').onsubmit=event=>{event.preventDefault();run($('agreement-join'),joinGroup);};$('agreement-sheet-form').onsubmit=event=>{event.preventDefault();run($('agreement-save'),saveSheet);};$('agreements-join-account').onclick=requireMember;$('agreements-refresh-list').onclick=()=>run($('agreements-refresh-list'),loadList);$('agreement-refresh').onclick=()=>run($('agreement-refresh'),()=>loadAgreement(activeId,true));$('agreement-load-latest').onclick=()=>{if(dirty)confirm('agreementsDiscardEditsConfirm',()=>{fillEditor();render();});else{fillEditor();render();}};
 $('agreement-add-task').onclick=()=>{if(editorTasks.length>=20||writing)return;editorTasks.push({id:crypto.randomUUID(),text:'',assigneeId:null,deadlineInput:'',timeZone:localZone(),originalDeadline:null,originalZone:localZone()});renderTasks();markDirty();$('agreement-task-'+editorTasks.at(-1).id).focus();};$('agreement-confirm').onclick=()=>run($('agreement-confirm'),()=>{const id=activeId,revision=agreement.revision;return mutate(()=>api(groupPath(id)+'/confirm','POST',{revision}),async()=>{await loadAgreement(id,true);toast('agreementsConfirmed');},id);});$('agreement-leave').onclick=()=>leaveGroup(activeId);$('agreement-delete').onclick=()=>deleteGroup(activeId);
 $('agreement-create-invite').onclick=()=>run($('agreement-create-invite'),()=>{const id=activeId;return mutate(()=>api(groupPath(id)+'/invites','POST',{}),async result=>{freshInvite=result.invite;await loadAgreement(id,true);renderInvites();},id);});$('agreement-copy-code').onclick=()=>run($('agreement-copy-code'),async()=>{if(!freshInvite)return;try{await navigator.clipboard.writeText(freshInvite.code);toast('agreementsCodeCopied');}catch{$('agreement-fresh-code').focus();$('agreement-fresh-code').select();toast('agreementsCopyManually');}});$('agreement-load-history').onclick=()=>run($('agreement-load-history'),loadHistory);$('agreement-restore-version').onclick=restoreVersion;$('agreement-export-text').onclick=()=>{if(!agreement||dirty)return;download(agreementText(agreement,language),'text/plain;charset=utf-8','txt');toast('agreementsExported');};$('agreement-print').onclick=printSheet;$('agreement-export-calendar').onclick=()=>run($('agreement-export-calendar'),()=>{if(!agreement||dirty)return;const selected=$('agreement-calendar-alert').value,remindMinutes=selected===''?null:Number(selected);download(agreementCalendar(agreement,{language,remindMinutes}),'text/calendar;charset=utf-8','ics');toast('agreementsCalendarExported');});
 render();return {render,memberChanged,resetMembers,invalidate};
}
